package cn.yuanxin.mvp.web.care;

import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;

import java.util.regex.Pattern;

/**
 * bigint 十进制字符串的契约化解析/输出（DD 3.1；contracts BigintString）。
 *
 * <p>契约 pattern {@code ^(0|[1-9][0-9]*)$}：只接受无符号十进制、无前导零
 * （"0" 合法）；非法/前导零/超 long 一律 400 INVALID_INPUT。</p>
 */
public final class CareBigints {

    private static final Pattern DECIMAL = Pattern.compile("^(0|[1-9][0-9]*)$");

    private CareBigints() {
    }

    /** 解析必填 bigint 字符串；非法/溢出 → 400 INVALID_INPUT。 */
    public static long parse(String raw, String field) {
        if (raw == null || !DECIMAL.matcher(raw).matches()) {
            throw invalid(field);
        }
        try {
            return Long.parseLong(raw);
        } catch (NumberFormatException overflow) {
            throw invalid(field);
        }
    }

    /** 解析可空 bigint 字符串；null → null，非法/溢出 → 400 INVALID_INPUT。 */
    public static Long parseNullable(String raw, String field) {
        return raw == null ? null : parse(raw, field);
    }

    /** 输出 bigint（必填）。 */
    public static String out(long value) {
        return Long.toString(value);
    }

    /** 输出 bigint（可空）。 */
    public static String out(Long value) {
        return value == null ? null : Long.toString(value);
    }

    private static ApiException invalid(String field) {
        return new ApiException(ErrorCode.INVALID_INPUT,
                field + " must be an unsigned decimal bigint string", java.util.Map.of("field", field));
    }
}

package cn.yuanxin.mvp.web.care;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

/**
 * T06 care_plans 只读单表仓储（显式列名，无 JOIN/无关联子查询）。
 *
 * <p>{@link CarePlanRow} 覆盖 Stage 2/3 所需全部列，避免后续返工；JSONB 列
 * 一律 {@code ::text} 取出后在投影层按字段规则映射。</p>
 */
@Repository
public class CarePlanRepository {

    private final JdbcTemplate jdbc;

    public CarePlanRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public record CarePlanRow(
            UUID id,
            UUID assessmentId,
            UUID memberId,
            String generationStatus,
            Long inputPhotoVersion,
            long generationRevision,
            String inputSnapshot,
            String planSummary,
            String planPayload,
            Long targetCount,
            long completedCount,
            Instant completedAt,
            long progressRevision,
            String failureDetail,
            Instant createdAt,
            Instant updatedAt) {
    }

    private static final String COLUMNS = "id, assessment_id, member_id, generation_status,"
            + " input_photo_version, generation_revision, input_snapshot::text AS input_snapshot,"
            + " plan_summary::text AS plan_summary, plan_payload::text AS plan_payload,"
            + " target_count, completed_count, completed_at, progress_revision,"
            + " failure_detail::text AS failure_detail, created_at, updated_at";

    private static final RowMapper<CarePlanRow> MAPPER = (rs, i) -> new CarePlanRow(
            rs.getObject("id", UUID.class),
            rs.getObject("assessment_id", UUID.class),
            rs.getObject("member_id", UUID.class),
            rs.getString("generation_status"),
            rs.getObject("input_photo_version", Long.class),
            rs.getLong("generation_revision"),
            rs.getString("input_snapshot"),
            rs.getString("plan_summary"),
            rs.getString("plan_payload"),
            rs.getObject("target_count", Long.class),
            rs.getLong("completed_count"),
            rs.getTimestamp("completed_at") == null ? null : rs.getTimestamp("completed_at").toInstant(),
            rs.getLong("progress_revision"),
            rs.getString("failure_detail"),
            rs.getTimestamp("created_at").toInstant(),
            rs.getTimestamp("updated_at").toInstant());

    public Optional<CarePlanRow> findById(UUID planId) {
        List<CarePlanRow> rows = jdbc.query(
                "SELECT " + COLUMNS + " FROM care_plans WHERE id = ?", MAPPER, planId);
        return rows.isEmpty() ? Optional.empty() : Optional.of(rows.get(0));
    }

    /**
     * 按成员（可选评估）键集分页：created_at DESC, id DESC。
     *
     * @param assessmentId 可空；非空时附加 {@code AND assessment_id = ?}
     * @param afterCreatedAt 可空游标排序值（第一页 null，省略游标谓词）
     * @param afterId        可空游标末位 ID
     * @param fetchSize     取 limit+1 以判断 nextCursor
     */
    public List<CarePlanRow> pageByMember(UUID memberId, UUID assessmentId,
                                          Instant afterCreatedAt, UUID afterId, int fetchSize) {
        StringBuilder sql = new StringBuilder("SELECT ").append(COLUMNS)
                .append(" FROM care_plans WHERE member_id = ?");
        java.util.List<Object> args = new java.util.ArrayList<>();
        args.add(memberId);
        if (assessmentId != null) {
            sql.append(" AND assessment_id = ?");
            args.add(assessmentId);
        }
        if (afterCreatedAt != null && afterId != null) {
            sql.append(" AND (created_at, id) < (?, ?)");
            args.add(Timestamp.from(afterCreatedAt));
            args.add(afterId);
        }
        sql.append(" ORDER BY created_at DESC, id DESC LIMIT ?");
        args.add(fetchSize);
        return jdbc.query(sql.toString(), MAPPER, args.toArray());
    }
}

package cn.yuanxin.mvp.web.care;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

/**
 * T07 care_executions 只读单表仓储（显式列名，无 JOIN/无关联子查询）。
 *
 * <p>{@link CareExecutionRow} 覆盖 Stage 2/3 所需全部列（控制端归属、核验
 * 代次、观测流、账本、收尾清单等）。</p>
 */
@Repository
public class CareExecutionRepository {

    private final JdbcTemplate jdbc;

    public CareExecutionRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public record CareExecutionRow(
            UUID id,
            UUID planId,
            UUID memberId,
            UUID microcrystalId,
            String controllerType,
            UUID controllerAccountId,
            String controllerInstallationId,
            UUID controllerGimbalId,
            UUID assessmentIdAtStart,
            String planSnapshot,
            String status,
            long verificationRevision,
            Instant lastVerifiedAt,
            String latestVerification,
            String observationEpoch,
            Long lastObservationSeq,
            String latestObservation,
            long acceptedCount,
            String closureManifest,
            Instant stoppedAt,
            Instant closedAt,
            UUID sourceRequestId,
            Instant createdAt,
            Instant updatedAt) {
    }

    private static final String COLUMNS = "id, plan_id, member_id, microcrystal_id,"
            + " controller_type, controller_account_id, controller_installation_id,"
            + " controller_gimbal_id, assessment_id_at_start, plan_snapshot::text AS plan_snapshot,"
            + " status, verification_revision, last_verified_at,"
            + " latest_verification::text AS latest_verification,"
            + " observation_epoch, last_observation_seq,"
            + " latest_observation::text AS latest_observation, accepted_count,"
            + " closure_manifest::text AS closure_manifest, stopped_at, closed_at,"
            + " source_request_id, created_at, updated_at";

    private static final RowMapper<CareExecutionRow> MAPPER = (rs, i) -> new CareExecutionRow(
            rs.getObject("id", UUID.class),
            rs.getObject("plan_id", UUID.class),
            rs.getObject("member_id", UUID.class),
            rs.getObject("microcrystal_id", UUID.class),
            rs.getString("controller_type"),
            rs.getObject("controller_account_id", UUID.class),
            rs.getString("controller_installation_id"),
            rs.getObject("controller_gimbal_id", UUID.class),
            rs.getObject("assessment_id_at_start", UUID.class),
            rs.getString("plan_snapshot"),
            rs.getString("status"),
            rs.getLong("verification_revision"),
            rs.getTimestamp("last_verified_at") == null ? null : rs.getTimestamp("last_verified_at").toInstant(),
            rs.getString("latest_verification"),
            rs.getString("observation_epoch"),
            rs.getObject("last_observation_seq", Long.class),
            rs.getString("latest_observation"),
            rs.getLong("accepted_count"),
            rs.getString("closure_manifest"),
            rs.getTimestamp("stopped_at") == null ? null : rs.getTimestamp("stopped_at").toInstant(),
            rs.getTimestamp("closed_at") == null ? null : rs.getTimestamp("closed_at").toInstant(),
            rs.getObject("source_request_id", UUID.class),
            rs.getTimestamp("created_at").toInstant(),
            rs.getTimestamp("updated_at").toInstant());

    public Optional<CareExecutionRow> findById(UUID executionId) {
        List<CareExecutionRow> rows = jdbc.query(
                "SELECT " + COLUMNS + " FROM care_executions WHERE id = ?", MAPPER, executionId);
        return rows.isEmpty() ? Optional.empty() : Optional.of(rows.get(0));
    }

    /**
     * 按成员键集分页（created_at DESC, id DESC），可选 planId 等值与 created_at
     * [from, to] 过滤；from/to 与游标均作用于 created_at。
     */
    public List<CareExecutionRow> pageByMember(UUID memberId, UUID planId, Instant from, Instant to,
                                               Instant afterCreatedAt, UUID afterId, int fetchSize) {
        StringBuilder sql = new StringBuilder("SELECT ").append(COLUMNS)
                .append(" FROM care_executions WHERE member_id = ?");
        List<Object> args = new ArrayList<>();
        args.add(memberId);
        if (planId != null) {
            sql.append(" AND plan_id = ?");
            args.add(planId);
        }
        if (from != null) {
            sql.append(" AND created_at >= ?");
            args.add(Timestamp.from(from));
        }
        if (to != null) {
            sql.append(" AND created_at <= ?");
            args.add(Timestamp.from(to));
        }
        if (afterCreatedAt != null && afterId != null) {
            sql.append(" AND (created_at, id) < (?, ?)");
            args.add(Timestamp.from(afterCreatedAt));
            args.add(afterId);
        }
        sql.append(" ORDER BY created_at DESC, id DESC LIMIT ?");
        args.add(fetchSize);
        return jdbc.query(sql.toString(), MAPPER, args.toArray());
    }
}

package cn.yuanxin.mvp.web.care;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.UUID;

/**
 * T08 care_records 只读单表仓储：记录流水位（MAX(source_seq) 聚合）与增量
 * 确认 ID 分页（显式列名，无 JOIN/无关联子查询）。绝不写入。
 */
@Repository
public class CareRecordRepository {

    private final JdbcTemplate jdbc;

    public CareRecordRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 指定执行流 epoch 下已接受记录的最大 source_seq；无记录或 epoch 为空 → 0。 */
    public long maxSourceSeq(UUID executionId, String sourceEpoch) {
        if (sourceEpoch == null) {
            return 0L;
        }
        Long value = jdbc.queryForObject(
                "SELECT COALESCE(MAX(source_seq), 0) FROM care_records"
                        + " WHERE execution_id = ? AND source_epoch = ?",
                Long.class, executionId, sourceEpoch);
        return value == null ? 0L : value;
    }

    /** client_record_id 按 source_seq 升序分页（source_seq &gt; afterSeq）。 */
    public List<String> clientRecordIdsAfter(UUID executionId, String sourceEpoch,
                                             long afterSeq, int limit) {
        if (sourceEpoch == null) {
            return List.of();
        }
        return jdbc.query("SELECT client_record_id FROM care_records"
                        + " WHERE execution_id = ? AND source_epoch = ? AND source_seq > ?"
                        + " ORDER BY source_seq LIMIT ?",
                (rs, i) -> rs.getString("client_record_id"), executionId, sourceEpoch, afterSeq, limit);
    }
}

