        assertEquals(1, d2.path("items").size());
        assertEquals(execA.toString(), d2.path("items").get(0).path("executionId").asText());

        // planId 过滤
        JsonNode byPlan = JSON.readTree(getExecutions(login.accessToken(), memberId,
